    "Station owner / ops assistant": "站点负责人 / 运营助理",
    "The station owner handles on-site management, rider communication, escalation, training delivery and daily results.": "站点负责人负责现场管理、骑手沟通、异常升级、培训落地和每日结果。",
    "Station operations": "站点运营",
    "Station ops SOP": "站点运营 SOP",
    "Check-in times, gear checklist, lateness list, backup records.": "签到时间、装备检查表、迟到名单、补位记录。",
    "Check-in sheet, document completeness, registration screenshots, no-show follow-up records.": "签到表、资料完整率、注册完成截图、未到场回访记录。",
    "System data principles": "系统数据原则",
    "System records": "系统记录",
    "Offline reception, document checks, training schedule, Ponto capacity, first-shift hosting.": "线下接待、资料核验、培训安排、Ponto 容量、首班承接。",
