    "Lead collection": "线索收集",
    "Lead status: to contact, booked, no-show, attended, docs pending, registering, binding, training, converted or eliminated.": "线索状态记录为待联系、已预约、未到场、已到场、资料待补、注册中、绑定中、培训中、已转化或淘汰。",
    "Lead intake": "线索进入",
    "Lead booking": "线索预约",
    "Bind/unbind requests must be approved or rejected within 96h; late ones expire and are auto-rejected.": "绑定/解绑申请必须在 96 小时内批准或拒绝；超时会自动过期并被系统拒绝。",
    "Binding successful": "绑定成功",
    "After HQ syncs the bound list, the station schedules Ponto, Leader, in-app chat, first-shift training and review.": "绑定成功名单由总部同步后，站点安排 Ponto、Leader、应用内聊天室、首班培训和首班复盘。",
    "After binding, join Ponto/Leader/groups, finish training, run the first shift and review full-time conversion.": "绑定成功后加入 Ponto/Leader/群组，完成培训，安排首班并复盘是否转全职。",
    "After binding, HQ syncs the station, which adds the rider to the Ponto, Leader, in-app chat and training list.": "绑定成功后，总部同步站点；站点再将骑手加入对应 Ponto、Leader、应用内聊天室和培训名单。",
    "Binding success rate": "绑定成功率",
    "Share of bound riders completing the first shift.": "绑定成功骑手中完成首个班次的人数占比。",
    "Binding status, failure reasons, handling time, overdue list.": "绑定状态、失败原因、处理时间、超时清单。",
    "Missing fields, amount gaps, unscheduled online, abnormal cancellations, complaints and accidents enter the ops queue.": "缺字段、金额差异、未排班上线、异常取消、投诉和事故进入运营队列。",
    "The group only publishes HQ-confirmed ops, scheduling, payment, training and safety info.": "群内只发布总部确认过的运营、排班、付款、培训和安全信息。",
    "Unfamiliar with rules": "规则不熟",
    "First contact within the set time: confirm moto, city, hours and intent, then send the offline registration address and required documents.": "规定时间内首次联系，确认 moto、城市、可工作时间、到场意愿，并发送线下注册地址和所需资料。",
    "Videos serve as PontoSys training material with the PDF manual for station managers and Leaders.": "视频作为 PontoSys 操作培训资料，配合 PDF 手册用于站点经理和 Leader 培训。",
    "Record completeness rate": "记录完整率",
    "Evidence verifiability rate": "证据可查率",
    "The owner handles the floor and exceptions; the assistant logs offline, rejection notes, complaints, accidents and group comms.": "负责人处理现场和异常；运营助理记录离线、拒单说明、投诉、事故和群沟通。",
    "Owner matrix": "负责人矩阵",
    "The owner confirms targets and risks; the assistant prepares check-in sheets, training lists, gear checks and group notices.": "负责人确认当日目标和风险；运营助理准备签到表、培训名单、装备检查和群通知。",
