    "PontoSys is MePonto's ops system receiving 99 data and scheduling tasks; not public, not a recruiting page, group script or rider training entry.": "PontoSys é o sistema operacional da MePonto que recebe dados da 99 e tarefas de escala; não é público nem entrada de recrutamento, scripts ou treinamento.",
