    "Fixed end-of-day sync by the station: online hours, completed orders, OPH, AR, exceptions and next-day plan.": "Alinhamento fixo no fim do dia pela estação: horas online, pedidos, OPH, AR, exceções e plano do dia seguinte.",
    "Failures don't enter the full-time roster; unbinding is handled by HQ via the PontoSys flow with financial settlement.": "Reprovados não entram na escala integral; desvínculo é feito pela matriz via PontoSys com acerto financeiro.",
    "Do not collect CPF, addresses or financial disputes in the group.": "Não coletar CPF, endereços ou disputas financeiras no grupo.",
    "Never abandon the final response to a Reclame Aqui complaint.": "Nunca abandonar a resposta final a uma reclamação no Reclame Aqui.",
    "Do not claim to be 99Food or publish official 99 policy.": "Não se apresentar como 99Food nem publicar política oficial da 99.",
