    "Accidents, personal safety, serious complaints, payment disputes, data anomalies and mass peak-hour offline must escalate to HQ.": "Acidentes, segurança pessoal, reclamações graves, disputas de pagamento, anomalias de dados e offline em massa no pico devem escalar à matriz.",
    "Accidents, complaints, payment disputes and data gaps must have an owner and a closure status.": "Acidentes, reclamações, disputas e divergências devem ter responsável e status de fechamento.",
    "Breaks and offline follow the rider system rules; anything beyond must be reported.": "Pausas e offline seguem o sistema; o que exceder deve ser reportado.",
    "After 99 app registration and platform review, HQ staff handle OL binding, scheduling and data checks in PontoSys.": "Após registro no app 99 e revisão da plataforma, a matriz faz o vínculo OL, escala e checagem no PontoSys.",
    "Candidates submit their own 99 app registration; the OL doesn't control platform review nor promises approval.": "O candidato envia o próprio registro no app 99; o OL não controla a revisão nem garante aprovação.",
    "Check candidates in, verify documents, explain the OL model, help with 99 app registration, mark attended/absent/docs pending.": "Registrar candidatos, checar documentos, explicar o modelo OL, ajudar no app 99 e marcar presença/ausência/pendências.",
    "Full-time rider": "Entregador em tempo integral",
    "Full-time riders / recruiting / station ops": "Tempo integral / recrutamento / operação da estação",
    "Full-time rider SOP": "SOP do entregador em tempo integral",
    "Daily actions of full-time riders from arrival, work start, peaks and night safety to wrap-up review.": "Ações diárias do tempo integral: chegada, início, picos, segurança noturna e revisão final.",
