    "Full-time rider daily SOP": "SOP diário do tempo integral",
    "Full-time rider daily flow": "Fluxo diário do tempo integral",
    "Confirm the candidate has a moto or can arrange one; bike not accepted in OL mode unless 99 says otherwise.": "Confirmar que o candidato tem moto ou consegue uma; bike não é aceita no OL salvo aviso da 99.",
    "Arrival reception": "Recepção de chegada",
    "Show-up rate": "Taxa de comparecimento",
    "Share of attendees completing 99 app registration/document submission.": "Proporção de presentes que concluem registro/envio de documentos no app 99.",
    "Share of attendees with complete documents able to enter registration/binding.": "Proporção de presentes com documentos completos aptos a registrar/vincular.",
    "Arrive at the Ponto": "Chegar ao Ponto",
    "Lunch & dinner peaks": "Picos de almoço e jantar",
    "Lunch peak": "Pico do almoço",
    "No going offline during lunch/dinner peaks; stay dispatchable in the assigned area.": "Proibido ficar offline nos picos; manter-se disponível na área designada.",
    "Help riders complete 99 app registration; platform review results are not promised by the OL.": "Ajudar no registro do app 99; o resultado da revisão não é garantido pelo OL.",
    "Dangerous driving": "Direção perigosa",
    "Two staff on site": "Dupla presente",
    "Two-person staffing": "Equipe de duas pessoas",
    "Back-office binding": "Vínculo no back-office",
    "Reconcile orders, online hours, TSH, AR, CAA and D+1/D+2 payables against 99 console reports.": "Conciliar pedidos, horas online, TSH, AR, CAA e valores D+1/D+2 com os relatórios da 99.",
    "Fixed-time review": "Revisão em horário fixo",
    "Online screenshots, exception logs, rejection notes, accident/complaint tickets.": "Capturas online, registros de exceções, justificativas de recusa, tíquetes de acidente/reclamação.",
    "Handle PontoSys bind/unbind; record success, failure, incomplete docs, failed review, duplicate binding etc.": "Tratar vínculos no PontoSys; registrar sucesso, falha, documentos incompletos, reprovação e duplicidade.",
    "Review TSH, AR, orders, delays, payments and next-day shifts.": "Revisar TSH, AR, pedidos, atrasos, pagamentos e escalas do dia seguinte.",
    "Review & handover": "Revisão e passagem de turno",
    "Night incidents: secure people first, then call emergency/police and the Leader, and open an Incident in the system.": "Incidentes noturnos: priorizar pessoas, acionar emergência/polícia e o Leader e abrir Incident no sistema.",
    "Night GPS": "GPS noturno",
    "Night GPS ping every 10 min": "GPS noturno a cada 10 min",
    "At night the system pings location every 10 minutes; station and Leader watch for abnormal stops.": "À noite o sistema envia localização a cada 10 min; estação e Leader monitoram paradas anormais.",
    "Report vehicle, document, phone or gear issues to the Leader before the shift and wait for handling.": "Reportar problemas de veículo, documentos, celular ou equipamento ao Leader antes do turno.",
    "Complete training on Ponto discipline, order flow, safety, payment, communication and incident handling.": "Concluir treinamento de disciplina do Ponto, fluxo de pedidos, segurança, pagamento, comunicação e incidentes.",
    "Training done": "Treinamento concluído",
    "Share entering the official 7h/8h/11h roster after the first shift.": "Proporção que entra na escala 7h/8h/11h após o primeiro turno.",
    "GPS log / Incident": "Registro de GPS / Incident",
    "GPS trail, 10-min logs, rejection notes, escalation records.": "Trilha de GPS, registros de 10 min, justificativas de recusa e escalonamentos.",
    "Externally mention only the delivery opportunity and offline registration; never show back-office screens or give riders access.": "Externamente, falar só da oportunidade e do registro presencial; nunca mostrar telas internas nem dar acesso.",
    "Import D-1 99 data and generate exceptions and payment gaps.": "Importar dados D-1 da 99 e gerar exceções e divergências de pagamento.",
    "Import into Riders, Pontos, Finance, Reports and Realtime keeping the batch number.": "Importar em Riders, Pontos, Finance, Reports e Realtime mantendo o número do lote.",
    "Export previous-day riders, shifts, orders, online hours, AR, cancellations, finance and guaranteed top-ups.": "Exportar entregadores, escalas, pedidos, horas online, AR, cancelamentos, finanças e complementos garantidos do dia anterior.",
    "Inspection evidence": "Evidências de inspeção",
    "Work hours": "Jornada de trabalho",
    "Share of booked riders who actually attend offline registration.": "Proporção de agendados que comparecem ao registro presencial.",
    "Start work": "Iniciar o trabalho",
    "Opening preparation": "Preparação de abertura",
    "Before opening": "Antes de abrir",
    "Before opening, both staff confirm shifts, expected arrivals, first-shift riders, risk riders, open incidents and key topics.": "Antes de abrir, a dupla confirma escalas, chegadas previstas, primeiros turnos, riscos, incidentes abertos e temas-chave.",
