    "Guide riders to the assigned station for explanation, document checks, 99 app registration and binding help.": "Encaminhar entregadores à estação designada para explicação, checagem, registro no app 99 e ajuda no vínculo.",
    "There are currently 5 official SOPs": "Atualmente há 5 SOPs oficiais",
    "Under observation": "Em observação",
    "Observation cases get a second shadow training focused on low AR, low OPH, lateness, offline or communication issues.": "Casos em observação recebem segundo treinamento focado em AR/OPH baixos, atrasos, offline ou comunicação.",
    "HQ/authorized staff handle PontoSys binding, approving or rejecting within 96h and recording failure reasons.": "Equipe autorizada trata vínculos no PontoSys, aprovando ou recusando em 96h e registrando motivos.",
    "Published by HQ": "Publicado pela matriz",
    "HQ back-office": "Back-office da matriz",
