    "HQ inspection": "Inspeção da matriz",
    "HQ inspection SOP": "SOP de inspeção da matriz",
    "HQ inspection must see screenshots, sheets, GPS, incident tickets or review records.": "A inspeção deve ver capturas, planilhas, GPS, tíquetes ou registros de revisão.",
    "HQ inspects stations for executed actions, complete records, verifiable evidence and closed exceptions.": "A matriz inspeciona execução, registros completos, evidências verificáveis e exceções fechadas.",
    "HQ inspection evidence": "Evidências de inspeção da matriz",
    "HQ marketing": "Marketing da matriz",
    "HQ marketing / HQ ops / station": "Marketing da matriz / operações da matriz / estação",
    "HQ campaigns": "Campanhas da matriz",
    "Stations receive HQ-campaign candidates: reception, document checks, rule briefing and registration help.": "A estação recebe candidatos das campanhas: recepção, checagem, briefing de regras e ajuda no registro.",
    "HQ recruiting campaigns, lead booking, offline registration, back-office binding, training, first shift and full-time conversion.": "Campanhas de recrutamento, agendamento de leads, registro presencial, vínculo, treinamento, primeiro turno e conversão.",
    "HQ data": "Dados da matriz",
    "HQ data must turn into station actions: who arrives, who completes docs, who does the first shift, who is at risk, whose payment to check.": "Dados da matriz viram ações: quem chega, quem completa documentos, quem faz o primeiro turno, quem é risco, que pagamento checar.",
    "HQ data support": "Suporte de dados da matriz",
    "HQ flags low TSH, low AR, high cancellation, complaints, accidents, payment gaps and consecutive absences.": "A matriz marca TSH/AR baixos, cancelamentos altos, reclamações, acidentes, divergências e faltas seguidas.",
    "HQ suggests daily shifts based on Ponto gaps, peak demand, night risk and historical capacity.": "A matriz sugere escalas com base em lacunas do Ponto, demanda de pico, risco noturno e capacidade histórica.",
    "HQ provides daily 99 D-1 data, shift suggestions, recruiting gaps, risk riders and finance gaps.": "A matriz fornece dados D-1 da 99, sugestões de escala, lacunas de recrutamento, riscos e divergências financeiras.",
    "HQ provides daily PontoSys D-1 exports: online hours, shifts, orders, AR, CAA, finance and exceptions.": "A matriz fornece exportações D-1 do PontoSys: horas online, turnos, pedidos, AR, CAA, finanças e exceções.",
    "HQ confirms city/Ponto gaps, target headcount, material versions, signup entry, offline sites, owners and daily capacity.": "A matriz confirma lacunas, metas, versões de material, entrada de inscrição, locais, responsáveis e capacidade diária.",
    "HQ publishes recruiting notices, marketing materials and signup entries; stations must not change the message.": "A matriz publica anúncios, materiais e entradas de inscrição; estações não alteram o discurso.",
    "HQ owns notices, materials, signup entries and conversion campaigns; stations own reception and training.": "A matriz cuida de anúncios, materiais, inscrições e campanhas; a estação cuida da recepção e do treinamento.",
    "HQ outputs per-station targets, candidate bookings, attendance lists, binding status and first-shift conversion.": "A matriz publica metas por estação, agendamentos, listas de presença, status de vínculo e conversão de primeiro turno.",
    "HQ operations": "Operações da matriz",
    "HQ ops / regional management": "Operações da matriz / gestão regional",
    "HQ ops / data": "Operações da matriz / dados",
    "All external materials must be HQ-approved; stations must not promise income, subsidies, policy or 99 official decisions.": "Todo material externo deve ser aprovado pela matriz; estações não prometem renda, subsídios, políticas ou decisões da 99.",
    "All hire/observe/eliminate reasons must be logged in PontoSys for channel quality analysis.": "Motivos de contratação/observação/desligamento devem ser registrados no PontoSys para análise de canais.",
