    "Recruiting conversion": "Conversão de recrutamento",
    "Recruiting demand is set by HQ from Ponto shift gaps, peak gaps, night gaps and the 7h/8h/11h roster.": "A demanda é definida pela matriz por lacunas de turnos, picos, noite e escala 7h/8h/11h.",
    "Rider recruiting SOP": "SOP de recrutamento de entregadores",
