    "Shift suggestion": "Sugestão de escala",
    "Minimum acceptance rate AR 95%; every rejection needs a traceable system reason.": "AR mínimo de 95%; toda recusa precisa de motivo rastreável no sistema.",
    "Receive HQ data": "Receber dados da matriz",
