    "Fixed wrap-up review: online hours, OPH, AR, exceptions, open items and next-day plan.": "Revisão fixa no fim: horas online, OPH, AR, exceções, pendências e plano do dia seguinte.",
    "Wrap-up review": "Revisão de encerramento",
    "Collect city/Ponto interest, contacts, moto ownership, available hours and arrival booking.": "Coletar interesse por cidade/Ponto, contatos, moto, horários disponíveis e agendamento.",
