    "Data foundation": "Base de dados",
    "Data morning meeting": "Reunião matinal de dados",
    "Data validation": "Validação de dados",
    "The Leader follows the new rider's first shift: check-in, going online, accepting, pickup/delivery, communication, GPS and reporting.": "O Leader acompanha o primeiro turno: check-in, online, aceite, coleta/entrega, comunicação, GPS e reportes.",
    "First-shift performance must be logged: check-in, online, OPH, AR, cancellations, complaints, accidents and conversion.": "Registrar o primeiro turno: check-in, online, OPH, AR, cancelamentos, reclamações, acidentes e conversão.",
    "No major complaints/accidents": "Sem reclamações/acidentes graves",
    "Daily close sheet, open-items list, next-day shift needs, HQ feedback form.": "Fechamento diário, pendências, necessidades de escala e formulário de feedback à matriz.",
    "Morning/afternoon shifts at the station, night shift confirmed online; check vehicle, phone, bag, rain gear, documents, fuel, brakes and tires.": "Manhã/tarde na estação, noite confirmada online; checar veículo, celular, bag, capa, documentos, combustível, freios e pneus.",
    "Morning/afternoon reference 11:00-14:00, 14:00-18:00; night reference 18:00-22:00.": "Manhã/tarde: 11:00-14:00 e 14:00-18:00; noite: 18:00-22:00.",
    "Morning/afternoon shifts clock out at the station; night shifts clock out online.": "Manhã/tarde batem ponto na estação; noite encerra online.",
