    "Clarify payment rules: order income D+1, guaranteed top-up D+2 if applicable; OL explains payment issues.": "Regras de pagamento: renda D+1, complemento garantido D+2 quando aplicável; o OL explica dúvidas.",
    "Evening/night shift": "Turno da noite/madrugada",
    "Evening/night online checks, handle accidents and complaints.": "Checagens online no pico noturno; tratar acidentes e reclamações.",
    "Morning meeting": "Reunião matinal",
    "Morning-meeting minutes, exception list, owner assignment, completion status.": "Ata da reunião, lista de exceções, responsáveis e status.",
    "Open accidents, complaints, payment disputes or serious exceptions cannot end the day without handover to the Leader or station owner.": "Pendências graves não encerram o dia sem passagem ao Leader ou responsável.",
    "Review D-1 data, shift suggestions, recruiting gaps, payment gaps, risk riders and open incidents.": "Ver dados D-1, sugestões de escala, lacunas, divergências, riscos e incidentes abertos.",
    "Check online hours, OPH, AR, open incidents/complaints, payment disputes and next-day shift needs.": "Conferir horas online, OPH, AR, pendências, disputas e necessidades do dia seguinte.",
    "Check online hours, OPH, AR, open incidents, complaints, payment disputes, next-day gaps and HQ support items.": "Conferir horas, OPH, AR, incidentes, reclamações, disputas, lacunas e apoios da matriz.",
    "Verify rider arrival, gear, vehicle, documents, phone battery, area and shift; flag and notify owner if absent.": "Verificar chegada, equipamento, veículo, documentos, bateria, área e turno; marcar ausências e avisar o responsável.",
    "Schedule offline registration by city and Ponto capacity; remind candidates to bring documents, phone, vehicle papers and contacts.": "Agendar registro presencial conforme capacidade; lembrar documentos, celular, papéis do veículo e contatos.",
    "Check PontoSys shift plans, shift registration and rider groups.": "Checar planos de escala, registro de turnos e grupos de entregadores no PontoSys.",
    "Check Rider ID, phone, Ponto, shift, order count, amounts, missing fields and duplicates.": "Checar Rider ID, telefone, Ponto, turno, pedidos, valores, campos faltantes e duplicidades.",
    "Check night GPS, abnormal stops, danger-zone rejection notes and safety escalations.": "Checar GPS noturno, paradas anormais, recusas em áreas de risco e escalonamentos.",
