    "Official SOP": "SOP oficial",
    "Every action must have PontoSys, check-in sheet, group record or back-office status.": "Toda ação precisa de PontoSys, folha de presença, registro de grupo ou status interno.",
    "Each station has 2 staff: station owner + ops assistant.": "Cada estação tem 2 pessoas: responsável + assistente de operações.",
    "Weekly system supports 6-on-1-off, 7-day continuous ops and station rosters published as needed.": "O sistema semanal permite 6x1, operação contínua de 7 dias e escala publicada pela estação.",
    "Each recruiting event": "Cada evento de recrutamento",
    "Daily capacity target uses OPH 1.5: 1.5 completed orders per online hour as the baseline.": "Meta diária com OPH 1,5: 1,5 pedidos por hora online como base.",
    "Before opening daily": "Antes da abertura diária",
    "Before daily wrap-up": "Antes do encerramento diário",
    "Daily morning meeting": "Reunião matinal diária",
    "Daily minimum online hours baseline is 7h; 8h and 11h shifts follow the system roster.": "Mínimo diário de 7h online; turnos de 8h e 11h seguem a escala do sistema.",
    "Daily open incidents, complaints, payment disputes and data gaps must be handed over formally, not verbally.": "Pendências diárias devem ter passagem formal, não verbal.",
    "2 staff per station": "2 pessoas por estação",
    "How a two-person station receives HQ data, opens, dispatches, hosts recruiting and escalates exceptions.": "Como a dupla recebe dados, abre a estação, despacha, recebe recrutamento e escala exceções.",
