    "Verify name, RG, CPF, e-mail, phone, city, vehicle and contacts on site; missing fields cannot enter binding.": "Verificar nome, RG, CPF, e-mail, telefone, cidade, veículo e contatos; faltas bloqueiam o vínculo.",
    "On-site check-in, document checks, OL model briefing, work hours, payment cycle, Ponto discipline and peak rules.": "Check-in, checagem, briefing do modelo OL, jornada, ciclo de pagamento, disciplina e regras de pico.",
    "On-site dispatch": "Despacho no local",
    "During shift": "Durante o turno",
    "During the shift track offline, low online, low AR, rejection notes, danger zones, accidents, complaints and payment disputes.": "No turno, acompanhar offline, AR baixo, recusas, áreas de risco, acidentes, reclamações e disputas.",
    "Before shift": "Antes do turno",
    "30 min before shift": "30 min antes do turno",
    "30 minutes before: check-in, gear check, area confirmation, no-offline peak briefing and night GPS reminder.": "30 min antes: check-in, equipamento, área, aviso de pico sem offline e lembrete de GPS noturno.",
    "Pre-shift check": "Checagem pré-turno",
    "Pre-shift check-in": "Check-in pré-turno",
    "Shift confirmation": "Confirmação de turno",
    "Green marks the actions riders must complete daily and on-site requirements.": "Verde marca as ações diárias obrigatórias e exigências no local.",
    "Watch peak online status, areas, offline, rejection notes, low AR/OPH, accidents and complaints; coordinate backup.": "Monitorar pico: online, áreas, offline, recusas, AR/OPH baixos, acidentes e reclamações; coordenar reforço.",
    "Confirm both staff present, daily targets, HQ data pack, risk riders, expected arrivals and open items.": "Confirmar dupla presente, metas, pacote de dados, riscos, chegadas previstas e pendências.",
    "Confirm bag, rain gear, documents, helmet and safety equipment are complete.": "Confirmar bag, capa de chuva, documentos, capacete e equipamentos de segurança.",
    "No offline; stay in the assigned area; abnormal orders go through platform flow first, then sync the Leader.": "Sem offline; permanecer na área; pedidos anormais seguem o fluxo da plataforma e depois avisam o Leader.",
    "No offline; GPS pings every 10 min; danger zones allow rejection with a submitted note.": "Sem offline; GPS a cada 10 min; áreas de risco permitem recusa com justificativa.",
    "Stations don't explain PontoSys externally nor show the back office; they only execute HQ tasks.": "A estação não explica o PontoSys nem mostra o sistema; só executa tarefas da matriz.",
    "If station data and reality diverge, report to HQ the same day for back-office recheck.": "Divergências entre dados e campo são reportadas no mesmo dia para rechecagem da matriz.",
    "Stations teach only execution rules riders need; back-office scheduling, PontoSys data and HQ accounts are not shown.": "A estação ensina só regras de execução; escalas internas, dados e contas da matriz não são exibidos.",
    "Station training": "Treinamento da estação",
    "Station daily flow": "Fluxo diário da estação",
