    "Lead response rate": "Taxa de resposta a leads",
    "Lead collection": "Coleta de leads",
    "Lead status: to contact, booked, no-show, attended, docs pending, registering, binding, training, converted or eliminated.": "Status do lead: a contatar, agendado, ausente, presente, docs pendentes, registrando, vinculando, treinando, convertido ou desligado.",
    "Lead intake": "Entrada de leads",
    "Lead booking": "Agendamento de leads",
    "Bind/unbind requests must be approved or rejected within 96h; late ones expire and are auto-rejected.": "Pedidos de vínculo/desvínculo devem ser decididos em 96h; atrasados expiram e são recusados.",
    "Binding successful": "Vínculo concluído",
    "After HQ syncs the bound list, the station schedules Ponto, Leader, in-app chat, first-shift training and review.": "Após a matriz sincronizar os vinculados, a estação agenda Ponto, Leader, chat, treinamento e revisão do primeiro turno.",
    "After binding, join Ponto/Leader/groups, finish training, run the first shift and review full-time conversion.": "Após o vínculo: entrar no Ponto/Leader/grupos, treinar, fazer o primeiro turno e revisar a conversão.",
